/* isry.itgcm.casemng.uneart.mapper.UnRegCaseMapper.selectUnRegCaseList */
SELECT * FROM ( SELECT #{TOT_CNT} AS TOT_CNT , ROWNUM AS SEQ , T11.* , (NVL(T11.ELESCH_STDENT_MALE_NOPE, 0) + NVL(T11.ELESCH_STDENT_FEMALE_NOPE, 0) + NVL(T11.MSKUL_STDENT_MALE_NOPE, 0) + NVL(T11.MSKUL_STDENT_FEMALE_NOPE, 0) + NVL(T11.HGSCHL_STDENT_MALE_NOPE, 0) + NVL(T11.HGSCHL_STDENT_FEMALE_NOPE, 0) + NVL(T11.UNIVA_STDENT_MALE_NOPE, 0) + NVL(T11.UNIVA_STDENT_FEMALE_NOPE, 0)) AS STDENT , (NVL(T11.ELESCH_OSCHL_MALE_NOPE, 0) + NVL(T11.ELESCH_OSCHL_FEMALE_NOPE, 0) + NVL(T11.MSKUL_OSCHL_MALE_NOPE, 0) + NVL(T11.MSKUL_OSCHL_FEMALE_NOPE, 0) + NVL(T11.HGSCHL_OSCHL_MALE_NOPE, 0) + NVL(T11.HGSCHL_OSCHL_FEMALE_NOPE, 0) + NVL(T11.UNIVA_OSCHL_MALE_NOPE, 0) + NVL(T11.UNIVA_OSCHL_FEMALE_NOPE, 0)) AS OSCHL , (NVL(T11.AGRDHS_IOCPTN_MALE_NOPE, 0) + NVL(T11.AGRDHS_EMPYMN_MALE_NOPE, 0) + NVL(T11.AGRDHS_IOCPTN_FEMALE_NOPE, 0) + NVL(T11.AGRDHS_EMPYMN_FEMALE_NOPE, 0)) AS AGRDHS , (NVL(T11.PARNTS_PRTCR_MALE_NOPE, 0) + NVL(T11.LEADER_MALE_NOPE, 0) + NVL(T11.PEPL_MALE_NOPE, 0) + NVL(T11.PARNTS_PRTCR_FEMALE_NOPE, 0) + NVL(T11.LEADER_FEMALE_NOPE, 0) + NVL(T11.PEPL_FEMALE_NOPE, 0)) AS STANDARD , TO_CHAR(TO_DATE(T11.SPRT_BGNG_YMD, 'YYYYMMDD'), 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(T11.SPRT_END_YMD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SUPPORT_PERIOD FROM ( SELECT UNREGI_CASE_NO , A.UNT_TASKWK_SE_CD , A.SPRT_BGNG_YMD , A.SPRT_END_YMD , A.SPRT_BGNG_HR , A.SPRT_END_HR , A.PLACE_NM , A.SRVC_PVSN_MTHD_SE_CD , A.SRVC_RESRCE_LCLAS_SE_CD , A.SRVC_RESRCE_MLSFC_SE_CD , A.SRVC_RESRCE_SCLAS_SE_CD , A.SRVC_RESRCE_DTL_SE_CD , A.SRVC_RESRCE_ETC_NM , A.PIC_NO , C##RG.DEC_B64(B.FLNM_ENCPT) AS PIC_NM , A.PIC_INST_NO , C.INST_NM AS PIC_INST_NM , A.SPRT_TTL_NM , A.SPRT_CN , A.ELESCH_STDENT_MALE_NOPE , A.ELESCH_STDENT_FEMALE_NOPE , A.MSKUL_STDENT_MALE_NOPE , A.MSKUL_STDENT_FEMALE_NOPE , A.HGSCHL_STDENT_MALE_NOPE , A.HGSCHL_STDENT_FEMALE_NOPE , A.UNIVA_STDENT_MALE_NOPE , A.UNIVA_STDENT_FEMALE_NOPE , A.ELESCH_OSCHL_MALE_NOPE , A.ELESCH_OSCHL_FEMALE_NOPE , A.MSKUL_OSCHL_MALE_NOPE , A.MSKUL_OSCHL_FEMALE_NOPE , A.HGSCHL_OSCHL_MALE_NOPE , A.HGSCHL_OSCHL_FEMALE_NOPE , A.UNIVA_OSCHL_MALE_NOPE , A.UNIVA_OSCHL_FEMALE_NOPE , A.AGRDHS_IOCPTN_MALE_NOPE , A.AGRDHS_EMPYMN_MALE_NOPE , A.AGRDHS_IOCPTN_FEMALE_NOPE , A.AGRDHS_EMPYMN_FEMALE_NOPE , A.PARNTS_PRTCR_MALE_NOPE , A.LEADER_MALE_NOPE , A.PEPL_MALE_NOPE , A.PARNTS_PRTCR_FEMALE_NOPE , A.LEADER_FEMALE_NOPE , A.PEPL_FEMALE_NOPE , A.SPRT_RESULT_CN , A.ATFINO , A.FRST_RGTR_ID , A.SRVC_PVSN_NO , A.FRST_REG_DT , A.LAST_MDFR_ID , A.LAST_MDFCN_DT FROM SED100 A, SCA100 B, SAA000 C WHERE A.PIC_NO = B.ENFSN_NO AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.PIC_INST_NO = C.INST_NO(+) AND A.FRST_REG_DT BETWEEN TO_DATE(#{REG_BGNG_YMD} || '000000' , 'YYYYMMDDHH24MISS') AND TO_DATE(#{REG_END_YMD} || '235959' , 'YYYYMMDDHH24MISS')
ORDER BY A.FRST_REG_DT DESC ) T11 ) T WHERE 1 = 1
AND T.SEQ >= #{START_IDX} AND T.SEQ <= #{LAST_IDX}

