/* isry.itgcm.casemng.uneart.mapper.UnRegCaseMapper.selectCnterSprtList */
SELECT T1.* FROM ( SELECT A.SGG_CNTER_SPRT_NO , A.UNT_TASKWK_SE_CD , A.SPRT_BGNG_YMD , A.SPRT_END_YMD , A.SPRT_BGNG_HR , A.SPRT_END_HR , A.PLACE_NM , A.PIC_NO , A.SRVC_PVSN_MTHD_SE_CD , A.SGG_CNTER_SPRT_SE_CD , A.SPRT_CNTER_CUNT , A.SPRT_NOPE , A.SPRT_TTL_NM , A.SPRT_CN , C##RG.DEC_B64(B.FLNM_ENCPT) AS PIC_NM , A.PIC_INST_NO , C.INST_NM AS PIC_INST_NM , A.ATFINO , A.FRST_RGTR_ID , TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT , TO_CHAR(TO_DATE(A.SPRT_BGNG_YMD, 'YYYYMMDD'), 'YYYY-MM-DD') || ' ~ ' || TO_CHAR(TO_DATE(A.SPRT_END_YMD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SUPPORT_PERIOD , A.LAST_MDFR_ID , A.LAST_MDFCN_DT , ROWNUM AS SEQ FROM SED120 A, SCA100 B, SAA000 C WHERE A.PIC_NO = B.ENFSN_NO AND A.PIC_INST_NO = C.INST_NO AND A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.FRST_REG_DT >= TO_DATE(#{REG_BGNG_YMD} || '000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{REG_END_YMD} || '235959', 'YYYYMMDDHH24MISS')
) T1 WHERE 1=1
AND T1.SEQ >= #{START_IDX} AND T1.SEQ <= #{LAST_IDX}

